        public static SolidColorBrush GetColor(string difficulty)
        {
            switch (difficulty.ToLower())
            {
                case "easy":
                    return new SolidColorBrush(Color.FromRgb(37, 244, 115));
                case "medium":
                    return Brushes.Yellow;
                case "hard":
                    return new SolidColorBrush(Color.FromRgb(232, 72, 72));
                default:
                    return Brushes.White;
            }
        }
        public static string ToCapitaizle(this string text)
        {
            return CultureInfo.CurrentCulture.TextInfo.ToTitleCase(text.Replace("-", " ").ToLower());
        }
        public static string ToHtml(this string text)
        {
            string htmlTemplate = @"
                    <!DOCTYPE html>
                    <html>
                    <head>
                        <style>
                            body {
                                background-color: #1f1f1f;
                                color: white;
                                font-family: Arial, sans-serif;
                                margin: 0;
                                padding: 10px;
                                scrollbar-face-color: #333;
                            }
                            pre, .example-block {
                                background-color: #333;
                                padding: 10px;
                                border-radius: 5px;
                            }
                            code {
                                font-weight: bold;
                                color: orange;
                                background: none;
                                padding: 0;
                                border: none;
                                font-size: 18px;
                            }
                            a {
                                color: #1e90ff;
                            }
                        </style>
                    </head>
                    <body>
                        ${content}
                    </body>
                    </html>";

            return htmlTemplate.Replace("${content}", text);

        }
